import React, { useState, useEffect, useRef } from 'react';
import socket from '../utils/socket';

const VideoChat = ({ onEndChat }) => {
  const localVideoRef = useRef(null);
  const remoteVideoRef = useRef(null);
  const peerConnection = useRef(null);

  const [stream, setStream] = useState(null);
  const [remoteStream, setRemoteStream] = useState(null);
  const [error, setError] = useState(null);
  const [isMicOn, setIsMicOn] = useState(true);
  const [isCamOn, setIsCamOn] = useState(true);
  const [timer, setTimer] = useState(0);
  const [status, setStatus] = useState('Connecting...');
  const [debugInfo, setDebugInfo] = useState({ socketId: '', waitingCount: 0 });

  // WebRTC Configuration
  const rtcConfig = {
    iceServers: [
      { urls: 'stun:stun.l.google.com:19302' },
      { urls: 'stun:stun1.l.google.com:19302' }
    ]
  };

  // Format seconds into MM:SS
  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  // Timer effect
  useEffect(() => {
    let interval;
    if (status === 'Connected') {
      interval = setInterval(() => {
        setTimer(prev => prev + 1);
      }, 1000);
    } else {
      setTimer(0);
    }
    return () => clearInterval(interval);
  }, [status]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      endCall();
      if (socket.connected) {
        socket.disconnect();
      }
    };
  }, []);

  // Initialize Socket and Media
  useEffect(() => {
    // Attempt socket connection immediately using the imported instance
    if (!socket.connected) {
      socket.connect();
    }

    const startCamera = async () => {
      try {
        const mediaStream = await navigator.mediaDevices.getUserMedia({
          video: true,
          audio: true
        });
        setStream(mediaStream);
        if (localVideoRef.current) {
          localVideoRef.current.srcObject = mediaStream;
        }

        // Only join waiting pool if we have media? 
        // Or join anyway and handle "no video" later?
        // For now, let's join.
        socket.emit('join-waiting');
        setStatus('Searching for partner...');

      } catch (err) {
        console.error("Error accessing media devices:", err);
        // Show specific error name
        setError(`Camera Error: ${err.name} - ${err.message}. Check permissions!`);

        // Still try to connect to socket to show we are online (even if cant video chat)
        // But maybe don't join/search if no video?
        // Let's at least show the socket ID to verify server connection.
      }
    };

    startCamera();
  }, []);

  // Robust Socket Listeners with RoomID tracking
  const roomIdRef = useRef(null);

  useEffect(() => {
    socket.on('matched', async ({ roomId, initiator }) => {
      roomIdRef.current = roomId;
      setStatus('Connected');

      const pc = new RTCPeerConnection(rtcConfig);
      peerConnection.current = pc;

      // Add Tracks
      if (localVideoRef.current && localVideoRef.current.srcObject) {
        localVideoRef.current.srcObject.getTracks().forEach(track => {
          pc.addTrack(track, localVideoRef.current.srcObject);
        });
      }

      pc.ontrack = (event) => {
        setRemoteStream(event.streams[0]);
        if (remoteVideoRef.current) {
          remoteVideoRef.current.srcObject = event.streams[0];
        }
      };

      pc.onicecandidate = (event) => {
        if (event.candidate) {
          socket.emit('ice-candidate', { candidate: event.candidate, roomId });
        }
      };

      if (initiator) {
        const offer = await pc.createOffer();
        await pc.setLocalDescription(offer);
        socket.emit('offer', { offer, roomId });
      }
    });

    socket.on('offer', async (offer) => {
      const pc = peerConnection.current;
      if (pc) {
        await pc.setRemoteDescription(new RTCSessionDescription(offer));
        const answer = await pc.createAnswer();
        await pc.setLocalDescription(answer);
        socket.emit('answer', { answer, roomId: roomIdRef.current });
      }
    });

    socket.on('answer', async (answer) => {
      const pc = peerConnection.current;
      if (pc) {
        await pc.setRemoteDescription(new RTCSessionDescription(answer));
      }
    });

    socket.on('ice-candidate', async (candidate) => {
      const pc = peerConnection.current;
      if (pc) {
        await pc.addIceCandidate(new RTCIceCandidate(candidate));
      }
    });

    socket.on('partner-disconnected', () => {
      setRemoteStream(null);
      if (remoteVideoRef.current) remoteVideoRef.current.srcObject = null;
      setStatus('Partner left. Searching...');
      setTimer(0);

      // Cleanup old connection
      if (peerConnection.current) {
        peerConnection.current.close();
        peerConnection.current = null;
      }

      // Auto-search
      socket.emit('join-waiting');
    });

    // Debug Listeners
    socket.on('connect', () => {
      setDebugInfo(prev => ({ ...prev, socketId: socket.id }));
    });

    socket.on('connect_error', (err) => {
      console.error("Socket connection error:", err);
      setError(`Socket Connection Failed: ${err.message}`);
    });

    socket.on('waiting-count', (count) => {
      setDebugInfo(prev => ({ ...prev, waitingCount: count }));
    });

    return () => {
      socket.off('matched');
      socket.off('offer');
      socket.off('answer');
      socket.off('ice-candidate');
      socket.off('partner-disconnected');
      socket.off('connect');
      socket.off('connect_error');
      socket.off('waiting-count');
    };
  }, []); // Run once to attach listeners

  // Helper to close connection
  const endCall = () => {
    if (peerConnection.current) {
      peerConnection.current.close();
      peerConnection.current = null;
    }
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
    }
    socket.emit('leave-room', { roomId: roomIdRef.current });
  };

  const toggleMic = () => {
    if (stream) {
      const audioTrack = stream.getAudioTracks()[0];
      if (audioTrack) {
        audioTrack.enabled = !audioTrack.enabled;
        setIsMicOn(audioTrack.enabled);
      }
    }
  };

  const toggleCam = () => {
    if (stream) {
      const videoTrack = stream.getVideoTracks()[0];
      if (videoTrack) {
        videoTrack.enabled = !videoTrack.enabled;
        setIsCamOn(videoTrack.enabled);
      }
    }
  };

  const handleNext = () => {
    // Close current peer connection
    if (peerConnection.current) {
      peerConnection.current.close();
      peerConnection.current = null;
    }
    setRemoteStream(null);
    if (remoteVideoRef.current) remoteVideoRef.current.srcObject = null;

    // Emit leave room and re-join waiting
    if (roomIdRef.current) {
      socket.emit('leave-room', { roomId: roomIdRef.current });
    }

    setStatus('Skipped. Searching...');
    setTimer(0);
    socket.emit('join-waiting');
  };

  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden flex flex-col">
      {/* Remote Video Area */}
      <div className="absolute inset-0 flex items-center justify-center bg-black">
        {remoteStream ? (
          <video
            ref={remoteVideoRef}
            autoPlay
            playsInline
            className="w-full h-full object-cover"
          />
        ) : (
          <div className="text-center text-white/50">
            <div className="text-6xl mb-4 animate-pulse">👤</div>
            <p className="text-xl font-light tracking-wide">{status}</p>
          </div>
        )}
      </div>

      {/* Top Bar / Status */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-center z-10 bg-gradient-to-b from-black/50 to-transparent">
        <div className="bg-black/40 backdrop-blur-md px-6 py-2 rounded-full border border-white/10 text-white flex items-center space-x-4">
          <span className={`w-2 h-2 rounded-full ${status === 'Connected' ? 'bg-green-500 animate-pulse' : 'bg-yellow-500'}`}></span>
          <span className="font-mono">{formatTime(timer)}</span>
          <span className="text-white/30">|</span>
          <span className="text-sm text-purple-200">{debugInfo.waitingCount} waiting</span>
          <span className="text-white/30">|</span>
          <span className="text-xs text-gray-400">{debugInfo.socketId ? `ID: ${debugInfo.socketId.slice(0, 4)}` : 'No ID'}</span>
        </div>
      </div>

      {/* Error Message */}
      {error && (
        <div className="absolute top-20 left-1/2 transform -translate-x-1/2 bg-red-500/90 text-white px-6 py-3 rounded-lg shadow-xl z-50">
          <p>{error}</p>
        </div>
      )}

      {/* Local Video Preview */}
      <div className="absolute bottom-24 right-6 w-32 md:w-48 aspect-[3/4] bg-black rounded-xl overflow-hidden shadow-2xl border-2 border-white/20 z-20 transition-all hover:scale-105">
        <video
          ref={localVideoRef}
          autoPlay
          playsInline
          muted
          className={`w-full h-full object-cover ${!isCamOn ? 'hidden' : ''}`}
        />
        {!isCamOn && (
          <div className="absolute inset-0 flex items-center justify-center bg-gray-800 text-white">
            <span className="text-2xl">📵</span>
          </div>
        )}
        <div className="absolute bottom-2 right-2 bg-black/60 px-2 py-0.5 rounded text-xs text-white font-medium">
          You
        </div>
      </div>

      {/* Control Bar */}
      <div className="absolute bottom-8 left-1/2 transform -translate-x-1/2 flex items-center space-x-4 z-30">
        {/* End Call */}
        <button
          onClick={onEndChat}
          className="w-14 h-14 bg-red-600 hover:bg-red-700 rounded-full flex items-center justify-center text-white shadow-lg shadow-red-600/30 transition-all hover:scale-110"
          title="End Call"
        >
          <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24">
            <path d="M12 9c-1.6 0-3.15.25-4.6.72v3.1c0 .39-.23.74-.56.9-.98.49-1.87 1.12-2.66 1.85-.18.18-.43.28-.7.28-.28 0-.53-.11-.71-.29L.29 13.08c-.18-.17-.29-.42-.29-.7 0-.28.11-.53.29-.71C3.34 8.78 7.46 7 12 7s8.66 1.78 11.71 4.67c.18.18.29.43.29.71 0 .28-.11.53-.29.71l-2.48 2.48c-.18.18-.43.29-.71.29-.27 0-.52-.11-.7-.28-.79-.74-1.69-1.36-2.67-1.85-.33-.16-.56-.5-.56-.9v-3.1C15.15 9.25 13.6 9 12 9z" />
          </svg>
        </button>

        {/* Mic Toggle */}
        <button
          onClick={toggleMic}
          className={`w-12 h-12 rounded-full flex items-center justify-center text-white transition-all hover:scale-105 ${isMicOn ? 'bg-gray-700 hover:bg-gray-600' : 'bg-red-500 hover:bg-red-600'}`}
          title={isMicOn ? "Mute Microphone" : "Unmute Microphone"}
        >
          {isMicOn ? (
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
          ) : (
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" strokeDasharray="20" strokeDashoffset="0"><animate attributeName="stroke-dashoffset" from="20" to="0" dur="0.2s" fill="freeze" /></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2" /></svg>
          )}
        </button>

        {/* Camera Toggle */}
        <button
          onClick={toggleCam}
          className={`w-12 h-12 rounded-full flex items-center justify-center text-white transition-all hover:scale-105 ${isCamOn ? 'bg-gray-700 hover:bg-gray-600' : 'bg-red-500 hover:bg-red-600'}`}
          title={isCamOn ? "Turn Off Camera" : "Turn On Camera"}
        >
          {isCamOn ? (
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
          ) : (
            <span className="text-xl">📵</span>
          )}
        </button>

        {/* Next Button */}
        <button
          onClick={handleNext}
          className="px-8 py-3 bg-white text-gray-900 rounded-full font-bold shadow-lg hover:shadow-xl hover:bg-gray-100 transition-all transform hover:-translate-y-1 active:translate-y-0"
        >
          Next ⏭️
        </button>
      </div>
    </div>
  );
};

export default VideoChat;
